function wolSearch(q){return 'https://wol.jw.org/es/wol/s/r4/lp-s?q='+encodeURIComponent(q)}
function jwSearch(q){return 'https://www.jw.org/es/busquedas/?q='+encodeURIComponent(q)}
const NOE=DATA.stories.find(s=>s.id==='noe');
if(NOE){Object.assign(NOE,{value:'Fe, integridad y constancia',summary:'Noé vivió en una sociedad que la Biblia describe como arruinada y llena de violencia. Los nefilim eran gigantes violentos e intimidantes. En ese ambiente Noé se mantuvo diferente, obedeció las instrucciones para construir el arca y trabajó con su familia durante años. Las escenas concretas de violencia del juego son una recreación educativa; la Biblia no describe cada incidente ni da una altura exacta de los nefilim.',sequence:['La tierra se llena de violencia y los nefilim intimidan a la gente.','Jehová da a Noé instrucciones detalladas para construir el arca.','Noé y su familia trabajan con constancia y reúnen provisiones.','Los animales entran y la familia de Noé se prepara para el Diluvio.'],modern:{context:'Amistades',situation:'Un grupo comparte videos de peleas, humillaciones y crueldad como si fueran entretenimiento, y te presiona para que te rías, participes o los reenvíes.',options:['No participar, explicar con calma tu límite y elegir algo diferente.','Reenviarlos para no quedar fuera del grupo.','Burlarte de la persona afectada aunque te incomode.'],correct:0,explanation:'Noé vivió rodeado de violencia, pero no permitió que el ambiente decidiera quién sería. La aplicación actual no consiste en aislarse de todos, sino en mantener límites y elegir conductas que no normalicen la crueldad.',action:'Identificar una situación en la que puedas rechazar con calma algo dañino y preparar de antemano qué dirás.',talk:'¿Cómo podemos mantener una conducta distinta sin sentirnos superiores a los demás?',responses:['Poner un límite claro sin atacar a nadie protege tus valores y evita contribuir a la violencia o humillación.','Reenviar algo dañino para encajar puede convertirte en parte del problema aunque no hayas iniciado la agresión.','Burlarte por presión del grupo refuerza una conducta que en realidad no quieres adoptar.'],line:'La meta no es ganar una discusión, sino decidir con anticipación qué clase de persona quieres ser.'},bridge:{past:'Noé se mantuvo diferente en una sociedad llena de violencia y siguió trabajando en lo que Jehová le había pedido.',value:'Fe, integridad y constancia',today:'A veces la violencia o la humillación se normalizan como entretenimiento o presión de grupo.',action:'Preparar una respuesta concreta para no participar en algo dañino.'}})}
