function objective(){const d=missionDefs[Math.min(state.mission,missionDefs.length-1)];const el=document.getElementById('objective');if(el)el.innerHTML=`<small>MISIÓN ${state.mission+1}/${missionDefs.length}</small><strong>${esc(d.t)}</strong><span>${esc(d.d)}</span>`;updateMarkers();updateWaypoint()}
