function updateMarkers(){missionMarkers.forEach(m=>m.active=false);const t=missionDefs[state.mission]?.target||'';if(noahMode){if(t==='memory')missionMarkers[0].active=true;if(t==='arkdoor')missionMarkers[1].active=true}else{if(t==='challenge')missionMarkers[0].active=true;if(t==='memory')missionMarkers[1].active=true;if(t==='portal')missionMarkers[2].active=true;if(t==='current')missionMarkers[0].active=true;if(t==='decision')missionMarkers[1].active=true}missionMarkers.forEach(m=>m.g.visible=m.active)}
function relevantNPC(){const t=missionDefs[state.mission]?.target||'';if(t.includes('npc0'))return 0;if(t.includes('npc1'))return 1;if(t.includes('npc2'))return 2;return -1}
function updateWaypoint(){let target=null,label='';if(noahMode){const t=missionDefs[state.mission]?.target||'';if(t==='danger3'){const z=noahDangerZones.find((_,i)=>!noahSeen.has(i));if(z){target=new THREE.Vector3(z.x,0,z.z);label='Escena de contexto'}}else if(t==='rescue'&&noahRescue){target=noahRescue.adult.position;label='Familia'}else if(t==='noah'&&noahGuide){target=noahGuide.obj.position;label='Noé'}else if(t==='materials3'){if(noahCarrying){target=noahDrop.pos;label='Entrega de madera'}else{const s=noahSupplies.find(x=>!x.taken);if(s){target=s.pos;label='Madera'}}}else if(t==='build3'){const q=noahTasks.find(x=>!noahTaskDone.has(x.idx));if(q){target=q.pos;label=q.label}}else if(t==='animals3'){const q=noahAnimals.find(x=>!noahAnimalsDone.has(x.idx));if(q){target=q.pos;label='Pareja de animales'}}else{const m=missionMarkers.find(x=>x.active);if(m){target=m.pos;label=m.label}}}else{const idx=relevantNPC();if(idx>=0){target=npcs[idx]?.mesh?.position;label='Personaje'}else{const m=missionMarkers.find(x=>x.active);if(m){target=m.pos;label=m.label}}}const el=document.getElementById('waypoint');if(!el)return;if(target){const d=player.position.distanceTo(target);el.innerHTML=`<b>◆ ${esc(label)} · ${Math.round(d)} m</b>`}else el.innerHTML=''}
