function interact(){let best=null,bd=3.1;for(const it of interactables){if(it.g && !it.active)continue;const pos=it.pos||it.obj?.position;if(!pos)continue;const d=player.position.distanceTo(pos);if(d<bd){bd=d;best=it}}if(!best){toast('Acércate al marcador, a un personaje o a un objetivo de misión.');return}if(noahMode){const t=missionDefs[state.mission]?.target||'';if(best.type==='rescue'&&t==='rescue'){noahRescued=true;best.adult.userData.escape=true;best.child.userData.escape=true;toast('La familia comienza a salir de la zona.');award(350);setTimeout(()=>advance('Familia a salvo'),900);return}if(best.type==='noah'&&t==='noah'){if(!noahSpoken){noahSpoken=true;pause(true);const d=document.createElement('div');d.className='dialogue';d.innerHTML=`<div class="who">NOÉ · JUNTO AL ARCA</div><p>La tierra estaba llena de violencia, pero Noé no dejó que ese ambiente definiera sus decisiones. Jehová le dio instrucciones concretas para construir el arca, y él las puso en práctica con su familia.</p><div class="actions"><button class="btn primary" id="noeContinue">Empezar a trabajar</button><a class="btn ghost" href="https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/G%C3%A9nesis/6/" target="_blank" rel="noopener">Génesis 6 ↗</a></div>`;root.appendChild(d);document.getElementById('noeContinue').onclick=()=>{d.remove();pause(false);award(400);advance('Encontraste a Noé')}}return}if(best.type==='supply'&&t==='materials3'&&!best.taken&&!noahCarrying){best.taken=true;best.obj.visible=false;best.beacon.visible=false;noahCarrying=best;carryBeam.visible=true;toast('Carga de madera recogida. Llévala al punto de entrega.');return}if(best.type==='dropzone'&&t==='materials3'&&noahCarrying){noahDelivered++;noahCarrying=null;carryBeam.visible=false;award(160);toast(`Madera entregada: ${noahDelivered}/3`);if(noahDelivered>=3)setTimeout(()=>advance('Materiales entregados'),500);return}if(best.type==='arktask'&&t==='build3'&&!noahTaskDone.has(best.idx)){noahTaskDone.add(best.idx);best.obj.visible=false;award(220);toast(`${best.label} · ${noahTaskDone.size}/3`);if(noahTaskDone.size>=3)setTimeout(()=>advance('Trabajo del arca completado'),500);return}if(best.type==='animalpair'&&t==='animals3'&&!noahAnimalsDone.has(best.idx)){noahAnimalsDone.add(best.idx);best.guided=true;best.obj.visible=false;award(250);toast(`Pareja guiada hacia el arca: ${noahAnimalsDone.size}/3`);if(noahAnimalsDone.size>=3)setTimeout(()=>advance('Animales encaminados'),700);return}if(best.type==='memory'&&t==='memory'){memoryGate(()=>{memoryDone=true;advance('Puerta superada')});return}if(best.type==='arkdoor'&&t==='arkdoor'){portalTransition();return}}
if(best.type==='npc'){const needed=relevantNPC();if(best.idx!==needed){toast('Ese personaje ya no tiene una misión activa.');return}openDialogue(best.idx)}else if(best.type==='challenge'&&missionDefs[state.mission]?.target==='challenge'){timelineChallenge(()=>{challengeDone=true;advance('Relato reconstruido')})}else if(best.type==='memory'&&missionDefs[state.mission]?.target==='memory'){memoryGate(()=>{memoryDone=true;advance('Puerta superada')})}else if(best.type==='portal'&&missionDefs[state.mission]?.target==='portal'){portalTransition()}else if(best.type==='current'&&missionDefs[state.mission]?.target==='current'){openCurrentBridge(()=>{currentDone=true;advance('Puente comprendido')})}else if(best.type==='decision'&&missionDefs[state.mission]?.target==='decision'){modernDecision()}}
function openDialogue(idx){pause(true);const role=phase==='ancient'?['Contexto','Acontecimiento','Enseñanza'][idx]:['Situación','Perspectiva','Aplicación'][idx];let text;if(phase==='ancient'){text=idx===0?state.story.summary:idx===1?(state.story.sequence?.slice(0,3).join(' → ')||state.story.summary):`La idea central que debes llevar contigo es ${state.story.value}. ${state.story.sequence?.[3]||''}`}else{text=idx===0?state.story.modern.situation:idx===1?state.story.modern.talk:state.story.modern.action}const d=document.createElement('div');d.className='dialogue';d.innerHTML=`<div class="who">${esc(role)} · ${esc(state.story.name)}</div><p>${esc(text)}</p><div class="actions"><button class="btn primary" id="dlgContinue">Continuar</button><a class="btn ghost" href="${state.story.source}" target="_blank" rel="noopener">Fuente ↗</a></div>`;root.appendChild(d);document.getElementById('dlgContinue').onclick=()=>{d.remove();pause(false);npcDone.add(idx);const t=missionDefs[state.mission]?.target||'';const count=phase==='ancient'?state.pearls:state.echoes;let ok=false;if(t==='npc0')ok=true;if(t==='pearls6npc1')ok=count>=6;if(t==='npc2pearls12')ok=count>=12;if(t==='echo2npc0')ok=count>=2;if(t==='echo4npc1')ok=count>=4;if(t==='echo6npc2')ok=count>=6;if(ok)advance(phase==='ancient'?'Testimonio descubierto':'Perspectiva escuchada');else objective()}}
function toast(msg){let e=document.getElementById('toast3d');if(!e){e=document.createElement('div');e.id='toast3d';e.style.cssText='position:absolute;z-index:55;left:50%;bottom:90px;transform:translateX(-50%);padding:10px 14px;border-radius:12px;background:#04101be8;border:1px solid #ffffff25;color:#fff;max-width:80%;font-size:12px';root.appendChild(e)}e.textContent=msg;clearTimeout(toast.t);toast.t=setTimeout(()=>e.remove(),1800)}
function pause(v){paused=v}
function setQuality(q){const pr=Math.min(devicePixelRatio||1,q==='ultra'?2.1:1.45);renderer.setPixelRatio(pr);composer.setPixelRatio(pr);sun.shadow.mapSize.set(q==='ultra'?4096:2048,q==='ultra'?4096:2048);gtaoPass.enabled=q==='ultra';bloomPass.enabled=q==='ultra'}
function resize(){const r=root.getBoundingClientRect();camera.aspect=r.width/r.height;camera.updateProjectionMatrix();renderer.setSize(r.width,r.height,false);composer.setSize(r.width,r.height)}
const keyMap={KeyW:'w',ArrowUp:'w',KeyS:'s',ArrowDown:'s',KeyA:'a',ArrowLeft:'a',KeyD:'d',ArrowRight:'d',ShiftLeft:'shift',ShiftRight:'shift',Space:'space'};function kd(e){if(keyMap[e.code]){keys[keyMap[e.code]]=true;if(e.code==='Space')e.preventDefault()}if(e.code==='KeyE')interact()}function ku(e){if(keyMap[e.code])keys[keyMap[e.code]]=false}addEventListener('keydown',kd);addEventListener('keyup',ku);
renderer.domElement.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'){dragging=true;px=e.clientX;py=e.clientY;renderer.domElement.setPointerCapture?.(e.pointerId)}});renderer.domElement.addEventListener('pointermove',e=>{if(!dragging)return;const dx=e.clientX-px,dy=e.clientY-py;px=e.clientX;py=e.clientY;yaw-=dx*.0032;pitch=Math.max(-.28,Math.min(.18,pitch-dy*.0024))});renderer.domElement.addEventListener('pointerup',()=>dragging=false);renderer.domElement.addEventListener('wheel',e=>{dist=Math.max(4.6,Math.min(9.5,dist+Math.sign(e.deltaY)*.45))},{passive:true});
