function collect(){for(const p of pearls){if(p.taken)continue;const dx=player.position.x-p.g.position.x,dz=player.position.z-p.g.position.z;if(dx*dx+dz*dz<2.0){p.taken=true;p.g.visible=false;if(phase==='ancient')state.pearls++;else state.echoes++;unlockReward(p.index,phase);const count=phase==='ancient'?state.pearls:state.echoes;const t=missionDefs[state.mission]?.target||'';if(!noahMode){if(t==='pearls3'&&count>=3)advance('Primeros hallazgos');if(t==='pearls6npc1'&&count>=6&&npcDone.has(1))advance('Investigación ampliada');if(t==='npc2pearls12'&&count>=12&&npcDone.has(2))advance('Enseñanza descubierta');}if(t==='echo2npc0'&&count>=2&&npcDone.has(0))advance('Situación explorada');if(t==='echo4npc1'&&count>=4&&npcDone.has(1))advance('Perspectiva completada');if(t==='echo6npc2'&&count>=6&&npcDone.has(2))advance('Preparación completada');objective()}}}
function animateHuman(g,t,speed,dt=.016){const rig=g.userData.rig;if(rig){rig.mixer.update(dt);const want=speed>1.25?'run':speed>.12?'walk':'idle';if(want!==rig.current&&rig.actions[want]){const from=rig.actions[rig.current],to=rig.actions[want];if(from)from.fadeOut(.18);to.reset().fadeIn(.18).play();rig.current=want}return}const l=g.userData.limbs;if(!l)return;const moving=Math.min(1.25,Math.max(0,speed)),pace=4.8+moving*4.6,a=Math.sin(t*pace)*.58*moving,b=Math.sin(t*pace+Math.PI)*.64*moving;l['arm-1'].rotation.x=a*.72;l['arm1'].rotation.x=-a*.72;l['leg-1'].rotation.x=b*.72;l['leg1'].rotation.x=-b*.72;if(l['knee-1'])l['knee-1'].rotation.x=Math.max(0,-b)*.45;if(l['knee1'])l['knee1'].rotation.x=Math.max(0,b)*.45;if(l['elbow-1'])l['elbow-1'].rotation.x=Math.max(0,a)*-.18;if(l['elbow1'])l['elbow1'].rotation.x=Math.max(0,-a)*-.18;if(g.userData.torso){g.userData.torso.rotation.z=Math.sin(t*pace*.5)*.018*moving;g.userData.torso.rotation.x=-.035*moving}if(g.userData.shoulders)g.userData.shoulders.rotation.y=Math.sin(t*pace)*.035*moving;if(g.userData.head)g.userData.head.rotation.y=Math.sin(t*pace*.5)*.018*moving;}
function minimap(){const c=document.getElementById('minimap');if(!c)return;const ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle='#03101a';ctx.fillRect(0,0,c.width,c.height);ctx.strokeStyle='#ffffff16';ctx.lineWidth=2;ctx.strokeRect(8,8,c.width-16,c.height-16);const sx=c.width/100,sz=c.height/150;function pt(x,z,col,r=5){ctx.fillStyle=col;ctx.beginPath();ctx.arc(c.width/2+x*sx,(72-z)*sz,r,0,Math.PI*2);ctx.fill()}pearls.forEach(p=>{if(!p.taken)pt(p.g.position.x,p.g.position.z,phase==='ancient'?'#67f2d8':'#ffd179',3)});markers.filter(m=>m.active).forEach(m=>pt(m.pos.x,m.pos.z,'#ff7a54',6));const ni=relevantNPC();if(ni>=0&&npcs[ni])pt(npcs[ni].mesh.position.x,npcs[ni].mesh.position.z,'#fff',5);pt(player.position.x,player.position.z,'#59dfff',6)}
const camLook=new THREE.Vector3(),desired=new THREE.Vector3(),forward=new THREE.Vector3(),right=new THREE.Vector3();const cameraRay=new THREE.Raycaster();let elapsed=0;const smoothFocus=new THREE.Vector3(player.position.x,2,player.position.z);const composer=new FX.EffectComposer(renderer);composer.addPass(new FX.RenderPass(scene,camera));const gtaoPass=new FX.GTAOPass(scene,camera,Math.max(1,mount.clientWidth),Math.max(1,mount.clientHeight));gtaoPass.enabled=state.quality==='ultra';composer.addPass(gtaoPass);const bloomPass=new FX.UnrealBloomPass(new THREE.Vector2(Math.max(1,mount.clientWidth),Math.max(1,mount.clientHeight)),.16,.34,1.05);bloomPass.enabled=state.quality==='ultra';composer.addPass(bloomPass);composer.addPass(new FX.OutputPass());setQuality(state.quality);resize();addEventListener('resize',resize);
function update(dt){if(paused)return;dt=Math.min(dt,.05);elapsed+=dt;let mx=(keys.d?1:0)-(keys.a?1:0),mz=(keys.w?1:0)-(keys.s?1:0);const inputLen=Math.hypot(mx,mz);if(inputLen>0){mx/=inputLen;mz/=inputLen}forward.set(-Math.sin(yaw),0,-Math.cos(yaw));right.set(Math.cos(yaw),0,-Math.sin(yaw));const dir=new THREE.Vector3().addScaledVector(forward,mz).addScaledVector(right,mx);if(dir.lengthSq()>0)dir.normalize();const targetSpeed=(keys.shift?SPRINT_SPEED:WALK_SPEED)*(inputLen>0?1:0);targetVelocity.copy(dir).multiplyScalar(targetSpeed);const accel=inputLen>0?(keys.shift?19.5:17.5):23;velocity.lerp(targetVelocity,1-Math.exp(-dt*accel));moveSpeed=velocity.length();if(moveSpeed>.045){const nx=player.position.x+velocity.x*dt,nz=player.position.z+velocity.z*dt;let hitX=false,hitZ=false;if(!collision(nx,player.position.z))player.position.x=nx;else hitX=true;if(!collision(player.position.x,nz))player.position.z=nz;else hitZ=true;if(hitX)velocity.x*=.18;if(hitZ)velocity.z*=.18;const ang=Math.atan2(-velocity.x,-velocity.z);let diff=((ang-player.rotation.y+Math.PI)%(Math.PI*2))-Math.PI;player.rotation.y+=diff*(1-Math.exp(-dt*22));turnLean=THREE.MathUtils.lerp(turnLean,THREE.MathUtils.clamp(diff*1.15,-.15,.15),1-Math.exp(-dt*12))}else turnLean*=Math.exp(-dt*12);if(keys.space&&onGround){vy=5.8;onGround=false;keys.space=false}vy-=17.5*dt;player.position.y+=vy*dt;if(player.position.y<=0){player.position.y=0;vy=0;onGround=true}if(player.userData.torso)player.userData.torso.rotation.z+=turnLean*.18;animateHuman(player,elapsed,moveSpeed/5.8,dt);
npcs.forEach((n,i)=>{animateHuman(n.mesh,elapsed+i,.02,dt)});ambientNpcs.forEach((n,i)=>{const p=elapsed*n.speed+n.phase,off=Math.sin(p)*n.range;if(n.axis==='x'){n.mesh.position.x=n.originX+off;n.mesh.rotation.y=off>=0?-Math.PI/2:Math.PI/2}else{n.mesh.position.z=n.originZ+off;n.mesh.rotation.y=off>=0?Math.PI:0}animateHuman(n.mesh,elapsed+n.phase,.36,dt)});if(noahMode){for(const a of noahActors){if(a.kind==='nephilim'){const off=Math.sin(elapsed*.38+a.phase)*a.range;a.mesh.position.x=a.cx+off;a.mesh.position.z=a.cz+Math.cos(elapsed*.31+a.phase)*1.1;a.mesh.rotation.y=off>=0?-Math.PI/2:Math.PI/2;animateHuman(a.mesh,elapsed+a.phase,.23,dt);const l=a.mesh.userData.limbs;if(l){l['arm-1'].rotation.x+=Math.sin(elapsed*2+a.phase)*.28;l['arm1'].rotation.x-=Math.sin(elapsed*2+a.phase)*.18}}else if(a.kind==='flee'){let target=a.target;if(a.mesh.userData.escape&&a===noahRescue?.adult)target=noahRescue.target;const dir=target.clone().sub(a.mesh.position);dir.y=0;if(dir.length()>.4){dir.normalize();a.mesh.position.addScaledVector(dir,dt*(a.mesh.userData.escape?3.4:2.35));a.mesh.rotation.y=Math.atan2(-dir.x,-dir.z);animateHuman(a.mesh,elapsed+a.phase,1.15,dt)}else animateHuman(a.mesh,elapsed+a.phase,.05,dt)}else if(a.kind==='builder'){animateHuman(a.mesh,elapsed+a.phase,.06,dt);const l=a.mesh.userData.limbs;if(l){l['arm-1'].rotation.x=-.7+Math.sin(elapsed*3+a.phase)*.45;l['arm1'].rotation.x=-.35-Math.sin(elapsed*3+a.phase)*.25}}}if(noahRescue?.adult?.userData.escape){const d=noahRescue.target.clone().sub(noahRescue.adult.position);d.y=0;if(d.length()>.4){d.normalize();noahRescue.adult.position.addScaledVector(d,dt*3.2);noahRescue.child.position.lerp(noahRescue.adult.position.clone().add(new THREE.Vector3(.8,0,.35)),1-Math.exp(-dt*5));animateHuman(noahRescue.adult,elapsed,1.15,dt);animateHuman(noahRescue.child,elapsed+.4,1.2,dt)}}for(const ap of noahAnimals){if(ap.guided){for(const an of ap.animals){const d=ap.target.clone().sub(an.position);d.y=0;if(d.length()>.7){d.normalize();an.position.addScaledVector(d,dt*1.35);an.rotation.y=Math.atan2(-d.x,-d.z)}}}}if(state.mission===0){for(let i=0;i<noahDangerZones.length;i++){if(noahSeen.has(i))continue;const z=noahDangerZones[i],dx=player.position.x-z.x,dz=player.position.z-z.z;if(dx*dx+dz*dz<45){noahSeen.add(i);toast(`${z.label} · Contexto ${noahSeen.size}/3`);award(120);if(noahSeen.size>=3)setTimeout(()=>advance('Comprendiste el ambiente'),650)}}}const nearG=noahActors.filter(a=>a.kind==='nephilim').reduce((m,a)=>Math.min(m,player.position.distanceTo(a.mesh.position)),999);const vign=document.getElementById('dangerVignette');if(vign)vign.style.opacity=String(Math.max(0,Math.min(.72,(10-nearG)/8)));if(noahRain){const targetRain=state.mission>=7?.74:state.mission>=6?.16:0;noahRain.ma.opacity=THREE.MathUtils.lerp(noahRain.ma.opacity,targetRain,1-Math.exp(-dt*2.5));const arr=noahRain.geo.attributes.position.array;for(let i=0;i<arr.length;i+=3){arr[i+1]-=dt*(18+((i/3)%7));if(arr[i+1]<.1){arr[i+1]=35+Math.random()*10;arr[i]=player.position.x+(Math.random()-.5)*90;arr[i+2]=player.position.z+(Math.random()-.5)*120}}noahRain.geo.attributes.position.needsUpdate=true;if(state.mission>=7){sun.intensity=THREE.MathUtils.lerp(sun.intensity,.65,1-Math.exp(-dt*.8));hemi.intensity=THREE.MathUtils.lerp(hemi.intensity,.46,1-Math.exp(-dt*.8));scene.fog.color.lerp(new THREE.Color(0x59636a),1-Math.exp(-dt*.35));}}}animatedProps.forEach((p,i)=>{if(p.type==='banner'&&p.cloth){p.cloth.rotation.y=Math.sin(elapsed*1.5+p.phase)*.08;p.cloth.rotation.z=Math.sin(elapsed*1.1+p.phase)*.018}else if(p.type==='animal'){p.g.position.y=Math.sin(elapsed*1.7+p.phase)*.012}else if(p.type==='dust'){p.g.rotation.y+=dt*.004}});pearls.forEach((p,i)=>{if(p.taken)return;p.g.rotation.y+=dt*.9;p.g.position.y=p.base+Math.sin(elapsed*2+i)*.16});missionMarkers.forEach((m,i)=>{if(m.g.visible){m.g.rotation.y+=dt*.5;m.g.position.y=Math.sin(elapsed*1.7+i)*.08}});collect();
smoothFocus.lerp(new THREE.Vector3(player.position.x,player.position.y+2.0,player.position.z),1-Math.exp(-dt*16));const focus=smoothFocus;const shoulder=new THREE.Vector3(Math.cos(yaw)*.48,0,-Math.sin(yaw)*.48);const rawDesired=new THREE.Vector3(focus.x+Math.sin(yaw)*Math.cos(pitch)*dist,focus.y+2.6+Math.sin(pitch)*dist,focus.z+Math.cos(yaw)*Math.cos(pitch)*dist).add(shoulder);const rayDir=rawDesired.clone().sub(focus);const rawDist=rayDir.length();rayDir.normalize();cameraRay.set(focus,rayDir);cameraRay.far=rawDist;const hits=cameraRay.intersectObjects(cameraObstacles,false);let safeDist=rawDist;if(hits.length)safeDist=Math.max(1.6,hits[0].distance-.42);desired.copy(focus).addScaledVector(rayDir,safeDist);camera.position.lerp(desired,1-Math.exp(-dt*13.5));camLook.lerp(focus,1-Math.exp(-dt*15));camera.lookAt(camLook);updateWaypoint();minimap()}
