function timelineChallenge(done){game?.pause(true);const items=state.story.sequence.map((text,i)=>({text,i})).sort(()=>Math.random()-.5);const o=document.createElement('div');o.className='overlay';o.innerHTML=`<section class="panel"><div class="eyebrow">Archivo de memoria</div><h2>Reconstruye el relato</h2><p>Arrastra los acontecimientos hasta colocarlos en el orden correcto. Todo pertenece al mismo relato.</p><div class="timeline" id="tl">${items.map(it=>`<div class="timeline-item" draggable="true" data-i="${it.i}">☷ &nbsp; ${esc(it.text)}</div>`).join('')}</div><div class="actions"><button class="btn primary" id="checkTl">Comprobar</button><button class="btn ghost" id="cancelTl">Volver al mundo</button></div><div id="tlFb"></div></section>`;document.getElementById('game').appendChild(o);let src=null;document.querySelectorAll('.timeline-item').forEach(t=>{t.ondragstart=()=>{src=t;t.classList.add('drag')};t.ondragend=()=>t.classList.remove('drag');t.ondragover=e=>e.preventDefault();t.ondrop=e=>{e.preventDefault();if(src&&src!==t){const b=document.getElementById('tl'),nodes=[...b.children],a=nodes.indexOf(src),bi=nodes.indexOf(t);b.insertBefore(src,a<bi?t.nextSibling:t)}}});document.getElementById('checkTl').onclick=()=>{const ok=[...document.querySelectorAll('.timeline-item')].every((t,i)=>Number(t.dataset.i)===i);if(ok){document.getElementById('tlFb').innerHTML=`<p style="color:var(--teal);font-weight:900">Relato reconstruido. +400 puntos</p>`;award(400);setTimeout(()=>{o.remove();game?.pause(false);done()},700)}else document.getElementById('tlFb').innerHTML='<p style="color:#ff9a9a">Aún hay acontecimientos fuera de orden.</p>'};document.getElementById('cancelTl').onclick=()=>{o.remove();game?.pause(false)}}
function memoryGate(done){game?.pause(true);let idx=1,hp=4;const o=document.createElement('div');o.className='overlay';o.innerHTML=`<section class="panel"><div class="eyebrow">Puerta de memoria</div><h2>Demuestra que comprendiste</h2><p>Cuatro preguntas del mismo relato. Cada acierto rompe un sello.</p><div id="mem"></div></section>`;document.getElementById('game').appendChild(o);function render(){const q=state.story.quizzes[idx];if(!q){award(500);o.remove();game?.pause(false);done();return}document.getElementById('mem').innerHTML=`<div class="stat">Sellos restantes <b>${hp}</b></div><h3 style="font-size:22px">${esc(q.question)}</h3><div class="answers">${q.options.map((x,i)=>`<button class="answer" data-i="${i}">${String.fromCharCode(65+i)} · ${esc(x)}</button>`).join('')}</div><div id="memFb"></div>`;document.querySelectorAll('#mem .answer').forEach(b=>b.onclick=()=>{if(Number(b.dataset.i)===q.correct){b.classList.add('good');document.getElementById('memFb').innerHTML=`<p style="color:#b9c7d3">${esc(q.explanation)}</p>`;idx++;hp--;setTimeout(render,700)}else{b.classList.add('bad');document.getElementById('memFb').innerHTML='<p style="color:#ffaaaa">Ese sello no cedió. Revisa el relato e inténtalo otra vez.</p>'}})}render()}
function openCurrentBridge(done){game?.pause(true);const o=document.createElement('div');o.className='overlay';o.innerHTML=`<section class="panel"><div class="eyebrow">Pasado ↔ presente</div><h2>${esc(state.story.value)}</h2><p><b>Entonces:</b> ${esc(state.story.bridge?.past||state.story.summary)}</p><p><b>Hoy:</b> ${esc(state.story.modern.situation)}</p><p>${esc(state.story.modern.talk)}</p><div class="actions"><button class="btn primary" id="bridgeDone">Seguir la misión</button><a class="btn ghost" href="${state.story.source}" target="_blank" rel="noopener">Revisar fuente ↗</a></div></section>`;document.getElementById('game').appendChild(o);document.getElementById('bridgeDone').onclick=()=>{o.remove();game?.pause(false);award(300);done()}}
function modernDecision(){game?.pause(true);const m=state.story.modern;const o=document.createElement('div');o.className='overlay';o.innerHTML=`<section class="panel"><div class="eyebrow">Misión final · actualidad</div><h2>¿Qué harías?</h2><p style="font-size:21px;color:white;font-weight:800">${esc(m.situation)}</p><div class="answers">${m.options.map((x,i)=>`<button class="answer" data-i="${i}">${String.fromCharCode(65+i)} · ${esc(x)}</button>`).join('')}</div><div id="decFb"></div></section>`;document.getElementById('game').appendChild(o);document.querySelectorAll('.answer',o).forEach(b=>b.onclick=()=>{const i=Number(b.dataset.i),ok=i===m.correct;document.querySelectorAll('.answer',o).forEach(x=>x.disabled=true);b.classList.add(ok?'good':'bad');document.getElementById('decFb').innerHTML=`<p><b>Posible consecuencia:</b> ${esc(m.responses?.[i]||m.explanation)}</p><div class="actions"><button class="btn primary" id="finishNow">Cerrar misión</button></div>`;award(ok?600:350);document.getElementById('finishNow').onclick=()=>{o.remove();game?.destroy();finalScreen()}})}
