function finalScreen(){const s=state.story,m=s.modern,bg=s.modernImage||DATA.modernImages[m.context]||s.image;app.innerHTML=`<section class="final"><img class="bg" src="${bg}" alt=""><div class="debrief"><div class="eyebrow">Debrief de misión · ${esc(s.name)}</div><h1>Lo que te llevas.</h1><div class="learning"><b>${esc(s.value)}:</b> ${esc(m.explanation)}</div><div class="journal"><label>¿Qué aprendí realmente?<textarea id="n1">${esc(state.notes.learn)}</textarea></label><label>¿Dónde puedo aplicarlo?<textarea id="n2">${esc(state.notes.apply)}</textarea></label><label>¿Qué acción haré y cuándo?<textarea id="n3">${esc(state.notes.when)}</textarea></label></div><div class="stats"><div class="stat">Puntos <b>${state.points.toLocaleString('es-ES')}</b></div><div class="stat">Nivel <b>${state.level}</b></div><div class="stat">Códice <b>${state.codex.length}</b></div></div><div class="actions"><button class="btn primary" id="saveFinal">Guardar reflexión</button><button class="btn" id="again">Repetir expedición</button><button class="btn ghost" id="other">Elegir otro relato</button></div><div class="footer">Relato: ${esc(s.reference)} · <a href="${s.source}" target="_blank" rel="noopener">publicación de origen en JW.ORG/WOL</a>. Las escenas son recreaciones educativas. En Noé, la violencia y los nefilim se basan en Génesis 6; acciones concretas, rutas, arquitectura y alturas son dramatizaciones y no se presentan como datos arqueológicos exactos.</div></div></section>`;document.getElementById('saveFinal').onclick=()=>{state.notes={learn:document.getElementById('n1').value,apply:document.getElementById('n2').value,when:document.getElementById('n3').value};save();document.getElementById('saveFinal').textContent='Guardado ✓'};document.getElementById('again').onclick=()=>{resetStory();startGame('ancient')};document.getElementById('other').onclick=selectStory}
